// The meta-model is written in Python, so the invariants follow the Python
// semantics of the arithmetic operations. In particular, the remainder of
// the modulo takes the sign of the divisor in Python (`-7 % 3 == 2`), while
// the native Go operator `%` gives the remainder with the sign of the dividend
// (`-7 % 3 == -1`). Therefore, we transpile the modulo to
// ourcommon.FloorMod instead of the native operator.
//
// The tests in this file document how the generated code behaves, and make sure
// that it matches the Python semantics.

// Test that the modulo follows the Python semantics, *i.e.*, the remainder takes
// the sign of the divisor.
func TestFloorMod(t *testing.T) {
	cases := []struct {
		dividend int64
		divisor  int64
		expected int64
	}{
		// both operands positive
		{7, 3, 1},
		// the remainder takes the sign of the positive divisor
		{-7, 3, 2},
		// the remainder takes the sign of the negative divisor
		{7, -3, -2},
		// both operands negative
		{-7, -3, -1},
		// divisible, positive dividend
		{6, 3, 0},
		// divisible, negative dividend
		{-6, 3, 0},
		// divisible, negative divisor
		{6, -3, 0},
		// zero dividend, positive divisor
		{0, 3, 0},
		// zero dividend, negative divisor
		{0, -3, 0},
		// dividend smaller than the positive divisor
		{2, 5, 2},
		// negative dividend smaller than the divisor
		{-2, 5, 3},
		// largest 64-bit integer, which is odd, by a positive divisor
		{math.MaxInt64, 2, 1},
		// largest 64-bit integer by a negative divisor
		{math.MaxInt64, -2, -1},
		// smallest 64-bit integer by a positive divisor
		{math.MinInt64, 3, 1},
		// smallest 64-bit integer by -1, which overflows with the native operator in some languages
		{math.MinInt64, -1, 0},
		// smallest 64-bit integer by the largest one
		{math.MinInt64, math.MaxInt64, 9223372036854775806},
	}

	for _, c := range cases {
		got := ourcommon.FloorMod(c.dividend, c.divisor)
		if got != c.expected {
			t.Errorf(
				"Expected FloorMod(%d, %d) to be %d, but got %d",
				c.dividend, c.divisor, c.expected, got,
			)
		}
	}
}

// Test the absolute value of 64-bit integers.
//
// Mind that the absolute value of the smallest 64-bit integer overflows,
// so we do not test it.
func TestAbsInt64(t *testing.T) {
	cases := []struct {
		argument int64
		expected int64
	}{
		{5, 5},
		{-5, 5},
		{0, 0},
		{math.MaxInt64, math.MaxInt64},
		{-math.MaxInt64, math.MaxInt64},
	}

	for _, c := range cases {
		got := ourcommon.AbsInt64(c.argument)
		if got != c.expected {
			t.Errorf(
				"Expected AbsInt64(%d) to be %d, but got %d",
				c.argument, c.expected, got,
			)
		}
	}
}

// Test the absolute value of floating-point numbers, for which we use
// the standard library.
func TestAbsFloat64(t *testing.T) {
	cases := []struct {
		argument float64
		expected float64
	}{
		{2.5, 2.5},
		{-2.5, 2.5},
		{0.0, 0.0},
		{math.Copysign(0, -1), 0.0},
		{-1.7976931348623157e+308, 1.7976931348623157e+308},
	}

	for _, c := range cases {
		got := math.Abs(c.argument)
		if got != c.expected {
			t.Errorf(
				"Expected math.Abs(%v) to be %v, but got %v",
				c.argument, c.expected, got,
			)
		}
	}
}

